}@media (prefers-reduced-motion: reduce) {
  [data-gatsby-loading-indicator="spinner"] { animation: 0s ease 0s 1 normal none running none; }
  [data-gatsby-loading-indicator-visible="false"] { transition: none 0s ease 0s; }
  [data-gatsby-loading-indicator-visible="true"] { transition: none 0s ease 0s; }
}@media (prefers-color-scheme: dark) {
  :host { --spinnerColor: #f1defa; --background: #232129; --color: #ffffff; }
}
